static const struct operator
{
  uchar prio;
  uchar flags;
} op_table[] =
{
            {0, 0},
             {16, (1 << 0)},
                 {12, (1 << 1) | (1 << 2)},
              {12, (1 << 1) | (1 << 2)},
              {14, (1 << 1) | (1 << 2)},
               {14, (1 << 1) | (1 << 2)},
              {15, (1 << 1) | (1 << 2)},
             {15, (1 << 1) | (1 << 2)},
             {15, (1 << 1) | (1 << 2)},
             {9, (1 << 1) | (1 << 2)},
            {7, (1 << 1) | (1 << 2)},
             {8, (1 << 1) | (1 << 2)},
                {13, (1 << 1)},
                {13, (1 << 1)},

             {10, (1 << 1) | (1 << 2)},
             {10, (1 << 1) | (1 << 2)},

               {16, (1 << 0)},
                 {6, (1 << 1)},
               {5, (1 << 1)},
               {3, 0},
               {4, (1 << 1) | (1 << 2)},
               {2, (1 << 1)},
                   {1, (1 << 0)},
                    {0, 0},
             {0, 0},
               {11, (1 << 1)},
                {11, (1 << 1)},
                   {12, (1 << 1) | (1 << 2)},
                 {12, (1 << 1) | (1 << 2)},
               {16, (1 << 0)},
                {16, (1 << 0)}
};
