  pres_cost = 2 * small_cost;

  start_sequence ();
  emit_move_insn (mem, reg1);
  emit_move_insn (reg2, mem);
  seq = get_insns ();
  end_sequence ();
  spill_cost_cfg = seq_cost (seq);
