static void
peel_loops_completely (struct loops *loops, int flags)
{
  struct loop *loop, *next;

  loop = loops->tree_root;
  while (loop->inner)
    loop = loop->inner;

  while (loop != loops->tree_root)
    {
      if (loop->next)
 {
   next = loop->next;
   while (next->inner)
     next = next->inner;
 }
      else
 next = loop->outer;

      loop->lpt_decision.decision = LPT_NONE;

      if (dump_file)
 fprintf (dump_file,
   "\n;; *** Considering loop %d for complete peeling ***\n",
   loop->num);

      loop->ninsns = num_loop_insns (loop);

      decide_peel_once_rolling (loop, flags);
      if (loop->lpt_decision.decision == LPT_NONE)
 decide_peel_completely (loop, flags);

      if (loop->lpt_decision.decision == LPT_PEEL_COMPLETELY)
 {
   peel_loop_completely (loops, loop);




 }
      loop = next;
    }
}


static void
decide_unrolling_and_peeling (struct loops *loops, int flags)
{
  struct loop *loop = loops->tree_root, *next;

  while (loop->inner)
    loop = loop->inner;


  while (loop != loops->tree_root)
    {
      if (loop->next)
 {
   next = loop->next;
   while (next->inner)
     next = next->inner;
 }
      else
 next = loop->outer;

      loop->lpt_decision.decision = LPT_NONE;

      if (dump_file)
 fprintf (dump_file, "\n;; *** Considering loop %d ***\n", loop->num);


      if (!maybe_hot_bb_p (loop->header))
 {
   if (dump_file)
     fprintf (dump_file, ";; Not considering loop, cold area\n");
   loop = next;
   continue;
 }


      if (!can_duplicate_loop_p (loop))
 {
   if (dump_file)
     fprintf (dump_file,
       ";; Not considering loop, cannot duplicate\n");
   loop = next;
   continue;
 }


      if (loop->inner)
 {
   if (dump_file)
     fprintf (dump_file, ";; Not considering loop, is not innermost\n");
   loop = next;
   continue;
 }

      loop->ninsns = num_loop_insns (loop);
      loop->av_ninsns = average_num_loop_insns (loop);




      decide_unroll_constant_iterations (loop, flags);
      if (loop->lpt_decision.decision == LPT_NONE)
 decide_unroll_runtime_iterations (loop, flags);
      if (loop->lpt_decision.decision == LPT_NONE)
 decide_unroll_stupid (loop, flags);
      if (loop->lpt_decision.decision == LPT_NONE)
 decide_peel_simple (loop, flags);

      loop = next;
    }
}



static void
decide_peel_once_rolling (struct loop *loop, int flags __attribute__ ((__unused__)))
{
  struct niter_desc *desc;

  if (dump_file)
    fprintf (dump_file, "\n;; Considering peeling once rolling loop\n");


  if ((unsigned) (compiler_params[(int) PARAM_MAX_ONCE_PEELED_INSNS].value) < loop->ninsns)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, is too big\n");
      return;
    }


  desc = get_simple_loop_desc (loop);


  if (!desc->simple_p
      || desc->assumptions
      || !desc->const_iter
      || desc->niter != 0)
    {
      if (dump_file)
 fprintf (dump_file,
   ";; Unable to prove that the loop rolls exactly once\n");
      return;
    }


  if (dump_file)
    fprintf (dump_file, ";; Decided to peel exactly once rolling loop\n");
  loop->lpt_decision.decision = LPT_PEEL_COMPLETELY;
}


static void
decide_peel_completely (struct loop *loop, int flags __attribute__ ((__unused__)))
{
  unsigned npeel;
  struct niter_desc *desc;

  if (dump_file)
    fprintf (dump_file, "\n;; Considering peeling completely\n");


  if (loop->inner)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, is not innermost\n");
      return;
    }


  if (!maybe_hot_bb_p (loop->header))
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, cold area\n");
      return;
    }


  if (!can_duplicate_loop_p (loop))
    {
      if (dump_file)
 fprintf (dump_file,
   ";; Not considering loop, cannot duplicate\n");
      return;
    }


  npeel = (compiler_params[(int) PARAM_MAX_COMPLETELY_PEELED_INSNS].value) / loop->ninsns;
  if (npeel > (unsigned) (compiler_params[(int) PARAM_MAX_COMPLETELY_PEEL_TIMES].value))
    npeel = (compiler_params[(int) PARAM_MAX_COMPLETELY_PEEL_TIMES].value);


  if (!npeel)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, is too big\n");
      return;
    }


  desc = get_simple_loop_desc (loop);


  if (!desc->simple_p
      || desc->assumptions
      || !desc->const_iter)
    {
      if (dump_file)
 fprintf (dump_file,
   ";; Unable to prove that the loop iterates constant times\n");
      return;
    }

  if (desc->niter > npeel - 1)
    {
      if (dump_file)
 {
   fprintf (dump_file,
     ";; Not peeling loop completely, rolls too much (");
   fprintf (dump_file, "%lld", desc->niter);
   fprintf (dump_file, " iterations > %d [maximum peelings])\n", npeel);
 }
      return;
    }


  if (dump_file)
    fprintf (dump_file, ";; Decided to peel loop completely\n");
  loop->lpt_decision.decision = LPT_PEEL_COMPLETELY;
}
