static void
decide_unroll_constant_iterations (struct loop *loop, int flags)
{
  unsigned nunroll, nunroll_by_av, best_copies, best_unroll = 0, n_copies, i;
  struct niter_desc *desc;

  if (!(flags & UAP_UNROLL))
    {

      return;
    }

  if (dump_file)
    fprintf (dump_file,
      "\n;; Considering unrolling loop with constant "
      "number of iterations\n");



  nunroll = (compiler_params[(int) PARAM_MAX_UNROLLED_INSNS].value) / loop->ninsns;
  nunroll_by_av
    = (compiler_params[(int) PARAM_MAX_AVERAGE_UNROLLED_INSNS].value) / loop->av_ninsns;
  if (nunroll > nunroll_by_av)
    nunroll = nunroll_by_av;
  if (nunroll > (unsigned) (compiler_params[(int) PARAM_MAX_UNROLL_TIMES].value))
    nunroll = (compiler_params[(int) PARAM_MAX_UNROLL_TIMES].value);


  if (nunroll <= 1)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, is too big\n");
      return;
    }


  desc = get_simple_loop_desc (loop);


  if (!desc->simple_p || !desc->const_iter || desc->assumptions)
    {
      if (dump_file)
 fprintf (dump_file,
   ";; Unable to prove that the loop iterates constant times\n");
      return;
    }


  if (desc->niter < 2 * nunroll)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not unrolling loop, doesn't roll\n");
      return;
    }





  best_copies = 2 * nunroll + 10;

  i = 2 * nunroll + 2;
  if (i - 1 >= desc->niter)
    i = desc->niter - 2;

  for (; i >= nunroll - 1; i--)
    {
      unsigned exit_mod = desc->niter % (i + 1);

      if (!loop_exit_at_end_p (loop))
 n_copies = exit_mod + i + 1;
      else if (exit_mod != (unsigned) i
        || desc->noloop_assumptions != (rtx) 0)
 n_copies = exit_mod + i + 2;
      else
 n_copies = i + 1;

      if (n_copies < best_copies)
 {
   best_copies = n_copies;
   best_unroll = i;
 }
    }

  if (dump_file)
    fprintf (dump_file, ";; max_unroll %d (%d copies, initial %d).\n",
      best_unroll + 1, best_copies, nunroll);

  loop->lpt_decision.decision = LPT_UNROLL_CONSTANT;
  loop->lpt_decision.times = best_unroll;

  if (dump_file)
    fprintf (dump_file,
      ";; Decided to unroll the constant times rolling loop, %d times.\n",
      loop->lpt_decision.times);
}
