static void
decide_unroll_runtime_iterations (struct loop *loop, int flags)
{
  unsigned nunroll, nunroll_by_av, i;
  struct niter_desc *desc;

  if (!(flags & UAP_UNROLL))
    {

      return;
    }

  if (dump_file)
    fprintf (dump_file,
      "\n;; Considering unrolling loop with runtime "
      "computable number of iterations\n");



  nunroll = (compiler_params[(int) PARAM_MAX_UNROLLED_INSNS].value) / loop->ninsns;
  nunroll_by_av = (compiler_params[(int) PARAM_MAX_AVERAGE_UNROLLED_INSNS].value) / loop->av_ninsns;
  if (nunroll > nunroll_by_av)
    nunroll = nunroll_by_av;
  if (nunroll > (unsigned) (compiler_params[(int) PARAM_MAX_UNROLL_TIMES].value))
    nunroll = (compiler_params[(int) PARAM_MAX_UNROLL_TIMES].value);


  if (nunroll <= 1)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not considering loop, is too big\n");
      return;
    }


  desc = get_simple_loop_desc (loop);


  if (!desc->simple_p || desc->assumptions)
    {
      if (dump_file)
 fprintf (dump_file,
   ";; Unable to prove that the number of iterations "
   "can be counted in runtime\n");
      return;
    }

  if (desc->const_iter)
    {
      if (dump_file)
 fprintf (dump_file, ";; Loop iterates constant times\n");
      return;
    }


  if (loop->header->count && expected_loop_iterations (loop) < 2 * nunroll)
    {
      if (dump_file)
 fprintf (dump_file, ";; Not unrolling loop, doesn't roll\n");
      return;
    }



  for (i = 1; 2 * i <= nunroll; i *= 2)
    continue;

  loop->lpt_decision.decision = LPT_UNROLL_RUNTIME;
  loop->lpt_decision.times = i - 1;

  if (dump_file)
    fprintf (dump_file,
      ";; Decided to unroll the runtime computable "
      "times rolling loop, %d times.\n",
      loop->lpt_decision.times);
}
