  reg = (((inc)->u.fld[0]).rtx);




  if (((enum rtx_code) (cmp)->code) != SET
      || (((cmp)->u.fld[0]).rtx) != (global_rtl[GR_PC])
      || ((enum rtx_code) ((((cmp)->u.fld[1]).rtx))->code) != IF_THEN_ELSE
      || ((enum rtx_code) (((((((cmp)->u.fld[1]).rtx))->u.fld[1]).rtx))->code) != LABEL_REF
      || ((((((cmp)->u.fld[1]).rtx))->u.fld[2]).rtx) != (global_rtl[GR_PC]))
    return 0;


