int
size_of_uleb128 (unsigned long value)
{
  int size = 0;

  do
    {
      value >>= 7;
      size += 1;
    }
  while (value != 0);

  return size;
}



int
size_of_sleb128 (long value)
{
  int size = 0, byte;

  do
    {
      byte = (value & 0x7f);
      value >>= 7;
      size += 1;
    }
  while (!((value == 0 && (byte & 0x40) == 0)
    || (value == -1 && (byte & 0x40) != 0)));

  return size;
}





