  do { sprintf (label, "*.%s%u", "LFB", (unsigned) ((cfun->funcdef_no))); } while (0)
                                      ;
  (*targetm.asm_out.internal_label) (asm_out_file, "LFB", (cfun->funcdef_no))
                                 ;
  current_function_func_begin_label = (__builtin_constant_p (label) ? get_identifier_with_length ((label), strlen (label)) : get_identifier (label));
