struct file_info
{
  char *path;
  char *fname;
  int length;
  int file_idx;
  int dir_idx;
};



struct dir_info
{
  char *path;
  int length;
  int prefix;
  int count;
  int dir_idx;
  int used;
};




static int
file_info_cmp (const void *p1, const void *p2)
{
  const struct file_info *s1 = p1;
  const struct file_info *s2 = p2;
  unsigned char *cp1;
  unsigned char *cp2;






  if ((s1->path == s1->fname || s2->path == s2->fname))
    return (s2->path == s2->fname) - (s1->path == s1->fname);

  cp1 = (unsigned char *) s1->path;
  cp2 = (unsigned char *) s2->path;

  while (1)
    {
      ++cp1;
      ++cp2;

      if ((cp1 == (unsigned char *) s1->fname)
   || (cp2 == (unsigned char *) s2->fname))
 return ((cp2 == (unsigned char *) s2->fname)
  - (cp1 == (unsigned char *) s1->fname));


      else if (*cp1 != *cp2)
 return *cp1 - *cp2;
    }
}





